def eligible(entries, required_features):
    """Return entries safe for the requested feature set."""
    result = []
    for entry in entries:
        # Must be enabled
        if not entry.get("enabled", True):
            continue
        # Must not be expired
        if entry.get("expired", False):
            continue
        # Price must be exactly numeric zero (0 or 0.0), not boolean, not string
        price = entry.get("price")
        if not isinstance(price, (int, float)) or isinstance(price, bool):
            continue
        if price != 0:
            continue
        # Must contain all required features
        features = set(entry.get("features", []))
        if not required_features.issubset(features):
            continue
        result.append(entry)
    return result
